// Reading and replacing a Markdown document with revision checks. The slim save model (owner ruling
// 2026-09-25): a read returns a content hash; a save names the hash it was based on; the writer re-reads,
// refuses on mismatch, then writes a same-directory temporary file and renames it over the target.
// Git is the backup �?" there is no journal or ReplaceFile backup. The hash check narrows but cannot close
// the window against an external editor writing between the re-read and the rename (see GOTCHAS).
import { createHash, randomBytes } from 'node:crypto';
import { promises as fs } from 'node:fs';
import path from 'node:path';

const BOM = '\uFEFF';
const RETRYABLE = new Set(['EPERM', 'EBUSY', 'EACCES']);

export class DocumentError extends Error {
  constructor(message, code) { super(message); this.code = code; }
}

export function revisionOf(bytes) {
  return `sha256:${createHash('sha256').update(bytes).digest('hex')}`;
}

/** Decode UTF-8 losslessly. Returns { text (no BOM), bom, revision, bytes }; `lossless` is false for invalid UTF-8. */
export function decode(bytes) {
  let text = bytes.toString('utf8');
  const bom = text.startsWith(BOM);
  if (bom) text = text.slice(1);
  const lossless = Buffer.compare(encode(text, bom), bytes) === 0;
  return { text, bom, lossless, revision: revisionOf(bytes), bytes };
}

export function encode(text, bom) {
  return Buffer.from(bom ? BOM + text : text, 'utf8');
}

export async function readDocument(file) {
  let bytes;
  try {
    bytes = await fs.readFile(file);
  } catch (err) {
    if (err.code === 'ENOENT') throw new DocumentError(`${file} does not exist.`, 'missing');
    if (RETRYABLE.has(err.code)) throw new DocumentError(`${path.basename(file)} is locked by another program (${err.code}).`, 'locked');
    throw new DocumentError(`Could not read ${file}: ${err.message}`, 'io');
  }
  return decode(bytes);
}

const delay = (ms) => new Promise((r) => { setTimeout(r, ms); });

/**
 * Replace `file` with `bytes` if its current content still hashes to `expectedRevision`.
 * Throws DocumentError 'conflict' (with .currentRevision) on a mismatch, 'locked' when another program
 * holds the file open past the retry budget, 'io' otherwise. The temporary file never outlives a failure.
 */
export async function replaceDocument(file, bytes, expectedRevision, { retries = 8 } = {}) {
  const current = await readDocument(file);
  if (current.revision !== expectedRevision) {
    const err = new DocumentError('The document changed since it was read.', 'conflict');
    err.currentRevision = current.revision;
    throw err;
  }
  const tmp = path.join(path.dirname(file), `.${path.basename(file)}.portal-${randomBytes(6).toString('hex')}.tmp`);
  try {
    await fs.writeFile(tmp, bytes, { flag: 'wx' });
    const handle = await fs.open(tmp, 'r+');
    try { await handle.sync(); } finally { await handle.close(); }
    for (let attempt = 0; ; attempt += 1) {
      try {
        await fs.rename(tmp, file);
        break;
      } catch (err) {
        if (!RETRYABLE.has(err.code) || attempt >= retries) {
          const code = RETRYABLE.has(err.code) ? 'locked' : 'io';
          throw new DocumentError(code === 'locked'
            ? `${path.basename(file)} is locked by another program (${err.code}); close it there and save again.`
            : `Could not replace ${file}: ${err.message}`, code);
        }
        await delay(25 * 2 ** Math.min(attempt, 5));
      }
    }
  } finally {
    await fs.rm(tmp, { force: true }).catch(() => {});
  }
  return revisionOf(bytes);
}

// Narrowly scoped edits to a parsed backlog. Each operation returns a list of span replacements against
// the ORIGINAL text; applyEdits splices them in. Nothing outside those spans changes, so BOM, line
// endings and hand formatting elsewhere survive byte for byte. Operations throw PatchError for requests
// the document cannot honour (unknown ID, malformed metadata, a stale target).
// A partitioned backlog (parseBacklogSet) works the same way: every edit names its `file` (null for a
// single-file backlog); index rows always live in the register; Mark done / Reopen move an entry between
// its open and done shards (src/backlog/shards.mjs).
import { randomBytes } from 'node:crypto';
import { FLAGS, ID_RE, PRIORITIES, PRIORITY_LABELS, fileOf, parseBacklog, parseBacklogSet, stripIdMarkers } from './parse.mjs';
import { addTarget, counterpartOf, insertionEdits, removalEdit } from './shards.mjs';
import { plain } from './status.mjs';

export const PORTAL_AREA = 'Added from the portal';
const PRIORITY_ORDER = Object.fromEntries(PRIORITIES.map((p, i) => [p, i]));

export class PatchError extends Error {
  constructor(message, code = 'invalid') { super(message); this.code = code; }
}

export function newId(taken = new Set()) {
  for (;;) {
    const id = `bl-${randomBytes(4).toString('hex')}`;
    if (!taken.has(id)) return id;
  }
}

export function applyEdits(text, edits) {
  const sorted = [...edits].sort((a, b) => b.start - a.start || b.end - a.end);
  for (let i = 1; i < sorted.length; i += 1) {
    if (sorted[i].end > sorted[i - 1].start) throw new PatchError('internal: overlapping edits', 'internal');
  }
  let out = text;
  for (const e of sorted) out = out.slice(0, e.start) + e.text + out.slice(e.end);
  return out;
}

/** Edits grouped by file and applied: Map(file -> new text). A single-file backlog uses the key null. */
export function applyEditsByFile(doc, edits) {
  const byFile = new Map();
  for (const e of edits) {
    const f = e.file ?? null;
    if (!byFile.has(f)) byFile.set(f, []);
    byFile.get(f).push(e);
  }
  const out = new Map();
  for (const [f, list] of byFile) {
    const base = f === null ? doc.text : doc.files.get(f).text;
    out.set(f, applyEdits(base, list));
  }
  return out;
}

/** The document as it would parse after `edits` (single file or the whole set). */
function reparse(doc, edits) {
  const changed = applyEditsByFile(doc, edits);
  if (!doc.set) return parseBacklog(changed.has(null) ? changed.get(null) : doc.text);
  const textOf = (rel) => (changed.has(rel) ? changed.get(rel) : doc.files.get(rel).text);
  return parseBacklogSet({ register: { rel: doc.rel, text: textOf(doc.rel) },
    shards: [...doc.files.keys()].filter((rel) => rel !== doc.rel).map((rel) => ({ rel, text: textOf(rel) })) });
}

/** The file an index-row edit belongs to. */
function regFile(doc) { return doc.set ? doc.rel : null; }
/** The file an entry edit belongs to. */
function itemFile(item) { return item.file ?? null; }

function marker(id) { return `<!-- ${id} -->`; }

export function flagsText(flags) {
  return ['research', 'ask'].filter((f) => flags.includes(f)).map((f) => FLAGS[f]).join('; ');
}

export function rowTitle(title) {
  let t = plain(title).replace(/\|/g, '\\|');
  if (t.length > 90) t = `${t.slice(0, 87)}�?�`;
  return t;
}

export function formatRow(id, priority, flags, title) {
  const p = priority === 'U' ? '�?"' : priority;
  return `| ${id} | ${p} | ${flagsText(flags)} | ${rowTitle(title)} |`;
}

// ---------- editable text of an item ----------

/**
 * The text the owner edits: the item without its list marker, continuation indent or ID marker.
 * `rawMode` means the item cannot be dedented losslessly and is edited verbatim (marker included).
 */
export function editableText(doc, item) {
  const eolRe = /\r?\n/;
  const raw = stripIdMarkers(item.raw);
  if (item.kind === 'heading') return { text: raw.split(eolRe).join('\n'), rawMode: true, indent: 0 };
  const lines = raw.split(eolRe);
  const w = item.marker.length;
  const out = [lines[0].slice(w)];
  for (const line of lines.slice(1)) {
    if (line.trim() === '') { out.push(''); continue; }
    if (!line.startsWith(' '.repeat(w))) return { text: lines.join('\n'), rawMode: true, indent: 0 };
    out.push(line.slice(w));
  }
  return { text: out.join('\n'), rawMode: false, indent: w };
}

function assembleItem(doc, item, id, edited, rawMode, eol = fileOf(doc, item).eol) {
  const lines = edited.replace(/\r\n?/g, '\n').replace(/\s+$/, '').split('\n');
  if (rawMode) {
    lines[0] = `${lines[0].replace(/\s+$/, '')} ${marker(id)}`;
    return lines.join(eol);
  }
  const w = item.marker.length;
  const first = `${item.marker}${lines[0].replace(/\s+$/, '')} ${marker(id)}`;
  const rest = lines.slice(1).map((l) => (l.trim() === '' ? '' : ' '.repeat(w) + l.replace(/\s+$/, '')));
  return [first, ...rest].join(eol);
}

function validateNewText(text) {
  if (typeof text !== 'string' || !text.trim()) throw new PatchError('The entry text is empty.');
  if (text.length > 20000) throw new PatchError('The entry text is longer than 20,000 characters.');
  if (/<!--\s*bl-/.test(text)) throw new PatchError('Remove the <!-- bl-�?� --> ID marker from the text; the portal keeps it.');
  if (/<!--\s*portal:/.test(text)) throw new PatchError('The text may not contain portal index markers.');
}

// ---------- lookup ----------

function findItem(doc, id) {
  if (!ID_RE.test(id || '')) throw new PatchError(`"${id}" is not an item ID.`);
  const matches = doc.items.filter((it) => it.id === id);
  if (matches.length === 0) throw new PatchError(`No entry carries ${id}; it may have been removed outside the portal.`, 'missing');
  if (matches.length > 1) throw new PatchError(`${id} appears on several entries; fix the duplicate first.`, 'malformed');
  const item = matches[0];
  if (item.problems.length) throw new PatchError(`${id} cannot be changed: ${item.problems[0]}.`, 'malformed');
  return item;
}

function requireIndex(doc) {
  if (!doc.index || doc.index.broken) {
    throw new PatchError('docs/BACKLOG.md has no usable "## Ranking index" table; run the backlog migration first.', 'malformed');
  }
  return doc.index;
}

function lineSpan(doc, lineIndex) {
  const l = doc.lines[lineIndex];
  return { start: l.start, end: l.next, text: doc.text.slice(l.start, l.next) };
}

function withEol(doc, s) { return s + doc.eol; }

/** Where a new row for `priority` goes: after its group's last row, else before the first lower-priority row. */
function rowInsertOffset(doc, priority, excludeId = null) {
  const index = requireIndex(doc);
  const rows = index.rows.filter((r) => r.id !== excludeId);
  const same = rows.filter((r) => r.priority === priority);
  if (same.length) return doc.lines[same[same.length - 1].lineIndex].next;
  const later = rows.find((r) => r.priority && PRIORITY_ORDER[r.priority] > PRIORITY_ORDER[priority]);
  if (later) return later.start;
  const last = rows.length ? rows[rows.length - 1].lineIndex : index.separatorLine;
  return doc.lines[last].next;
}

// ---------- operations ----------

export function opEdit(doc, { id, text }) {
  const item = findItem(doc, id);
  validateNewText(text);
  const current = editableText(doc, item);
  if (text.replace(/\r\n?/g, '\n') === current.text) return [];
  const replacement = assembleItem(doc, item, id, text, current.rawMode);
  const edits = [{ file: itemFile(item), start: item.start, end: item.end, text: replacement }];
  if (item.row) {
    const probe = reparse(doc, edits);
    const updated = probe.items.find((it) => it.id === id);
    if (updated && rowTitle(updated.title) !== item.row.entry) {
      const span = lineSpan(doc, item.row.lineIndex);
      edits.push({ file: regFile(doc), start: span.start, end: span.end, text: withEol(doc, formatRow(id, item.row.priority, item.row.flags, updated.title)) });
    }
  }
  return edits;
}

export function opSetPriority(doc, { id, priority }) {
  if (!PRIORITIES.includes(priority)) throw new PatchError(`Unknown priority "${priority}".`);
  const item = findItem(doc, id);
  requireIndex(doc);
  if (!item.row) return opIndex(doc, { id, priority }).edits;
  if (item.row.priority === priority) return [];
  const span = lineSpan(doc, item.row.lineIndex);
  const at = rowInsertOffset(doc, priority, id);
  const row = withEol(doc, formatRow(id, priority, item.row.flags, item.title));
  if (at === span.start || at === span.end) return [{ file: regFile(doc), start: span.start, end: span.end, text: row }];
  return [{ file: regFile(doc), start: span.start, end: span.end, text: '' }, { file: regFile(doc), start: at, end: at, text: row }];
}

export function opSetFlags(doc, { id, flags }) {
  if (!Array.isArray(flags) || flags.some((f) => !(f in FLAGS))) throw new PatchError('Flags must be a list of "research" and/or "ask".');
  const item = findItem(doc, id);
  requireIndex(doc);
  if (!item.row) throw new PatchError(`${id} is not in the ranking index yet; add it to the index first.`);
  const next = [...new Set(flags)].sort();
  if (next.join() === [...item.row.flags].sort().join()) return [];
  const span = lineSpan(doc, item.row.lineIndex);
  return [{ file: regFile(doc), start: span.start, end: span.end, text: withEol(doc, formatRow(id, item.row.priority, next, item.title)) }];
}

/** Move a ranked item before `beforeId` (same priority), or to the end of its priority when beforeId is null. */
export function opMove(doc, { id, beforeId = null }) {
  const item = findItem(doc, id);
  requireIndex(doc);
  if (!item.row) throw new PatchError(`${id} is not ranked yet; add it to the index first.`);
  if (beforeId === id) return [];
  const span = lineSpan(doc, item.row.lineIndex);
  let at;
  if (beforeId) {
    const target = findItem(doc, beforeId);
    if (!target.row || target.row.priority !== item.row.priority) {
      throw new PatchError(`${beforeId} is not ranked in ${PRIORITY_LABELS[item.row.priority]}.`);
    }
    at = target.row.start;
  } else {
    at = rowInsertOffset(doc, item.row.priority, id);
  }
  if (at === span.start || at === span.end) return [];
  return [{ file: regFile(doc), start: span.start, end: span.end, text: '' }, { file: regFile(doc), start: at, end: at, text: span.text.endsWith('\n') ? span.text : withEol(doc, span.text) }];
}

/**
 * Put an unindexed entry into the ranking index (end of its priority). An entry without an ID is
 * addressed by `key` + `line` (both from the read the client made) and receives a new ID first.
 */
export function opIndex(doc, { id = null, key = null, priority = null }) {
  requireIndex(doc);
  let item;
  const edits = [];
  if (id) {
    item = findItem(doc, id);
  } else {
    item = doc.items.find((it) => it.key === key);
    if (!item) throw new PatchError('That entry moved or changed since the page loaded; refresh and try again.', 'stale');
    if (item.id) throw new PatchError('That entry already has an ID.', 'stale');
    id = newId(new Set(doc.items.map((it) => it.id).filter(Boolean)));
    const first = fileOf(doc, item).lines[item.startLine];
    const firstText = first.text.replace(/\s+$/, '');
    edits.push({ file: itemFile(item), start: first.start, end: first.end, text: `${firstText} ${marker(id)}` });
  }
  if (item.row) throw new PatchError(`${id} is already ranked.`);
  const p = priority || item.section.priority;
  if (!PRIORITIES.includes(p)) throw new PatchError(`Unknown priority "${p}".`);
  const at = rowInsertOffset(doc, p);
  edits.push({ file: regFile(doc), start: at, end: at, text: withEol(doc, formatRow(id, p, [], item.title)) });
  return { edits, id };
}

// ---------- complete / reopen ----------

function todayIso() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function splitHeadingPrefix(kind, line0) {
  if (kind !== 'heading') return { prefix: '', rest: line0 };
  const m = /^(#{1,6}[ \t]+)([\s\S]*)$/.exec(line0);
  if (!m) throw new PatchError('internal: heading lead malformed', 'internal');
  return { prefix: m[1], rest: m[2] };
}

const DONE_WRAP_RE = /^~~([\s\S]*)~~ Done \d{4}-\d{2}-\d{2}\.(?: ([\s\S]*))?$/;
const REOPEN_WRAP_RE = /^\*\*[^*]+, then reopened \d{4}-\d{2}-\d{2}\.\*\*(?: ([\s\S]*))?$/;

/** Undo the portal's own done/reopen wrapping (one or several cycles deep) to recover the entry's real
 * content, so repeated Mark done / Reopen round trips never compound status text into the lead. Leaves
 * anything else (a hand-written status, an untouched open lead) alone. */
function coreLead(text) {
  let rest = text;
  for (let i = 0; i < 8; i += 1) {
    const done = DONE_WRAP_RE.exec(rest);
    if (done) { rest = done[2] ? `${done[1]} ${done[2]}` : done[1]; continue; }
    const reopen = REOPEN_WRAP_RE.exec(rest);
    if (reopen) { rest = reopen[1] || ''; continue; }
    break;
  }
  return rest;
}

/** The struck-through "done" lead: wraps the entry's real content (unwrapping any earlier portal cycle
 * first) �?" the common case is a lead that already is exactly `**Title.**`, giving the canonical
 * `~~**Title.**~~` �?" in `~~�?�~~`, then appends " Done <date>." and the optional note. Never called on an
 * already-struck (ambiguous) lead: the ~~�?�~~ the parser looks for is non-greedy and would match wrong. */
function doneLead(kind, line0, date, note) {
  const { prefix, rest } = splitHeadingPrefix(kind, line0);
  const bare = coreLead(rest);
  const noteSuffix = note ? ` ${note.trim()}` : '';
  return `${prefix}~~${bare}~~ Done ${date}.${noteSuffix}`;
}

/** The bold "reopened" lead the parser recognises (a DONE_WORD lead containing "reopened", not struck
 * through), followed by the entry's real content (unwrapped the same way as doneLead). Reuses the
 * entry's own "done" note (its lead status word) rather than inventing a new date. The status word's
 * date goes in parentheses right after it �?" `Done (2026-09-24), then reopened �?�` �?" so extractTitle's own
 * convention (a status prefix immediately followed by a comma falls through to whatever trails the
 * closing bold) keeps the entry's title readable, matching the hand-written "FIXED (date), then
 * reopened, �?�" entries already in the backlog. */
function reopenLead(kind, line0, statusNote, date) {
  const { prefix, rest } = splitHeadingPrefix(kind, line0);
  const bare = coreLead(rest);
  const dated = /^(\w+)\s+(\d{4}-\d{2}-\d{2})/.exec(statusNote || '');
  const base = dated ? `${dated[1]} (${dated[2]})` : (statusNote || 'Done').replace(/\.+$/, '');
  return `${prefix}**${base}, then reopened ${date}.**${bare ? ` ${bare}` : ''}`;
}

const COMPLETABLE_STATUSES = new Set(['open', 'partial', 'reopened']);

/** Mark an open/partial/reopened entry done: strike its lead, drop its index row (done entries have none). */
export function opComplete(doc, { id, note = null }) {
  const item = findItem(doc, id);
  if (item.status === 'done') return [];
  if (!COMPLETABLE_STATUSES.has(item.status)) {
    throw new PatchError(`${id}'s status is ambiguous; fix its lead in docs/BACKLOG.md before marking it done.`);
  }
  if (note !== null && (typeof note !== 'string' || note.length > 280)) {
    throw new PatchError('The note may be at most 280 characters.');
  }
  const editable = editableText(doc, item);
  const lines = editable.text.replace(/\r\n?/g, '\n').split('\n');
  lines[0] = doneLead(item.kind, lines[0], todayIso(), note);
  const edits = rewriteOrMove(doc, item, id, lines.join('\n'), editable.rawMode, 'done');
  if (item.row) {
    const span = lineSpan(doc, item.row.lineIndex);
    edits.push({ file: regFile(doc), start: span.start, end: span.end, text: '' });
  }
  return edits;
}

/**
 * The entry rewritten in place, or, in a partitioned backlog, moved to its counterpart shard: an open
 * shard's entry marked done goes to done/<same name>.md and a done shard's entry reopened goes back to
 * open/<same name>.md, under the same section and area. Anything else is rewritten where it is.
 */
function rewriteOrMove(doc, item, id, edited, rawMode, toward) {
  const dest = doc.set ? counterpartOf(item.file) : null;
  const fromOpen = item.file && item.file.includes('/open/');
  const moves = dest && doc.files.has(dest) && (toward === 'done' ? fromOpen : !fromOpen);
  if (!moves) return [{ file: itemFile(item), start: item.start, end: item.end, text: assembleItem(doc, item, id, edited, rawMode) }];
  const destDoc = doc.files.get(dest);
  const block = assembleItem(doc, item, id, edited, rawMode, destDoc.eol);
  return [removalEdit(fileOf(doc, item), item.file, item),
    ...insertionEdits(destDoc, dest, { sectionTitle: item.section.title, areaTitle: item.kind === 'heading' ? null : item.section.area, block })];
}

/** Reopen a done entry: bold "reopened" lead, and a fresh index row at the bottom of its priority group. */
export function opReopen(doc, { id, priority = null }) {
  const item = findItem(doc, id);
  if (item.status !== 'done') throw new PatchError(`${id} is not marked done.`);
  if (item.row) throw new PatchError(`${id} already has a ranking-index row.`);
  requireIndex(doc);
  const p = priority || item.priority || item.section.priority;
  if (!PRIORITIES.includes(p)) throw new PatchError(`Unknown priority "${p}".`);
  const editable = editableText(doc, item);
  const lines = editable.text.replace(/\r\n?/g, '\n').split('\n');
  lines[0] = reopenLead(item.kind, lines[0], item.statusNote, todayIso());
  const edits = rewriteOrMove(doc, item, id, lines.join('\n'), editable.rawMode, 'open');
  const at = rowInsertOffset(doc, p);
  edits.push({ file: regFile(doc), start: at, end: at, text: withEol(doc, formatRow(id, p, [], item.title)) });
  return edits;
}

/**
 * Append a new entry under a `### <area>` sub-heading (default "Added from the portal") at the end of
 * its priority section, and rank it last. `area` lets a bulk importer (e.g. import-gap.mjs) file entries
 * under its own named, dated sub-heading instead of the portal's own filing area, while still going
 * through the same index/verify machinery as every other add.
 */
export function opAdd(doc, { priority, text, area = PORTAL_AREA }) {
  if (!PRIORITIES.includes(priority)) throw new PatchError(`Unknown priority "${priority}".`);
  validateNewText(text);
  requireIndex(doc);
  const id = newId(new Set(doc.items.map((it) => it.id).filter(Boolean)));
  // A partitioned backlog files the entry in the open shard that already holds its area, else the default shard.
  const file = doc.set ? addTarget(doc, (t) => sectionMatches(t, priority), area) : null;
  if (doc.set && !file) throw new PatchError('The backlog has no open shard to add to (docs/work/backlog/open/portal.md is missing).', 'malformed');
  const fd = doc.set ? doc.files.get(file) : doc;
  const lines = text.replace(/\r\n?/g, '\n').replace(/\s+$/, '').split('\n');
  const body = [`- ${lines[0].replace(/\s+$/, '')} ${marker(id)}`,
    ...lines.slice(1).map((l) => (l.trim() === '' ? '' : `  ${l.replace(/\s+$/, '')}`))].join(fd.eol);
  const section = findSection(fd, priority, area);
  const edits = [];
  if (section.portalArea) {
    const at = fd.lines[section.portalArea.lastContent].next;
    edits.push({ file, start: at, end: at, text: withEol(fd, body) });
  } else {
    const lastLine = section.lastContent;
    const at = fd.lines[lastLine].next;
    const block = `${fd.eol}### ${area}${fd.eol}${body}${fd.eol}`;
    edits.push({ file, start: at, end: at, text: fd.lines[lastLine].next === fd.lines[lastLine].end ? fd.eol + block : block });
  }
  const title = reparse(doc, edits).items.find((it) => it.id === id)?.title || lines[0];
  const at = rowInsertOffset(doc, priority);
  edits.push({ file: regFile(doc), start: at, end: at, text: withEol(doc, formatRow(id, priority, [], title)) });
  return { edits, id };
}

function findSection(doc, priority, areaTitle = PORTAL_AREA) {
  const heads = [];
  doc.lines.forEach((l, i) => {
    const m = /^(#{2,3})[ \t]+(.*?)[ \t#]*$/.exec(l.text);
    if (m) heads.push({ level: m[1].length, title: m[2], line: i });
  });
  const h2 = heads.filter((h) => h.level === 2);
  const start = h2.find((h) => sectionMatches(h.title, priority));
  if (!start) throw new PatchError(`docs/BACKLOG.md has no "## ${PRIORITY_LABELS[priority]}" section to add to.`, 'malformed');
  const nextH2 = h2.find((h) => h.line > start.line);
  const end = nextH2 ? nextH2.line : doc.lines.length;
  const lastContent = lastNonBlank(doc, start.line, end);
  const area = heads.find((h) => h.level === 3 && h.line > start.line && h.line < end && h.title.trim() === areaTitle);
  let portalArea = null;
  if (area) {
    const next = heads.find((h) => h.line > area.line);
    const areaEnd = next && next.line < end ? next.line : end;
    portalArea = { line: area.line, lastContent: lastNonBlank(doc, area.line, areaEnd) };
  }
  return { start: start.line, end, lastContent, portalArea };
