function sectionMatches(title, priority) {
  const t = title.trim();
  return priority === 'U' ? /wishlist|unprioritized/i.test(t) : new RegExp(`^${priority}\\b`).test(t);
}

function lastNonBlank(doc, from, to) {
  let last = from;
  for (let i = from; i < to; i += 1) if (doc.lines[i].text.trim()) last = i;
  return last;
}

const OPS = { edit: opEdit, priority: opSetPriority, flags: opSetFlags, move: opMove, complete: opComplete, reopen: opReopen };

/**
 * Apply one portal operation to `text`. Returns { text, changed, id, op } �?" `changed` is false for a no-op.
 * The result is re-parsed and checked so a patch can never silently drop or duplicate an entry.
