export function applyOperation(text, op) {
  const doc = parseBacklog(text);
  let edits;
  let id = op.id || null;
  if (op.type === 'add') ({ edits, id } = opAdd(doc, op));
  else if (op.type === 'index') ({ edits, id } = opIndex(doc, op));
  else if (OPS[op.type]) edits = OPS[op.type](doc, op);
  else throw new PatchError(`Unknown operation "${op.type}".`);
  if (!edits.length) return { text, changed: false, id };
  const next = applyEdits(text, edits);
  if (next === text) return { text, changed: false, id };
  verify(doc, parseBacklog(next), op, id);
  return { text: next, changed: true, id };
