/**
 * Apply one portal operation to a partitioned backlog: `files` is { register: { rel, text }, shards:
 * [{ rel, text }] }. Returns { texts: Map(rel -> new text) holding only the files that changed, changed, id }.
 * Verified the same way as a single file, across the whole set.
 */
export function applyOperationSet(files, op) {
  const doc = parseBacklogSet(files);
  let edits;
  let id = op.id || null;
  if (op.type === 'add') ({ edits, id } = opAdd(doc, op));
  else if (op.type === 'index') ({ edits, id } = opIndex(doc, op));
  else if (OPS[op.type]) edits = OPS[op.type](doc, op);
  else throw new PatchError(`Unknown operation "${op.type}".`);
  if (!edits.length) return { texts: new Map(), changed: false, id };
  const next = applyEditsByFile(doc, edits);
  for (const [rel, text] of next) if (text === doc.files.get(rel).text) next.delete(rel);
  if (!next.size) return { texts: next, changed: false, id };
  verify(doc, reparse(doc, edits), op, id);
  return { texts: next, changed: true, id };
}

function verify(before, after, op, id) {
  const count = (d) => d.items.filter((it) => it.id).length;
  const expectedIds = count(before) + (op.type === 'add' || (op.type === 'index' && !op.id) ? 1 : 0);
  if (count(after) !== expectedIds || after.items.filter((it) => it.id === id).length !== 1) {
    throw new PatchError('That change would merge or split entries (check list markers and headings in the text).', 'structure');
  }
  const expectedItems = before.items.length + (op.type === 'add' ? 1 : 0);
  if (after.items.length !== expectedItems) {
    throw new PatchError('That change would add or remove other entries; keep the text to one entry (indent sub-points).', 'structure');
  }
  const rows = (d) => (d.index ? d.index.rows.length : 0);
  const hadRow = Boolean(before.items.find((it) => it.id === id)?.row);
  const expectedRows = rows(before)
    + (op.type === 'add' || op.type === 'index' || op.type === 'reopen' || (op.type === 'priority' && !hadRow) ? 1 : 0)
    - (op.type === 'complete' && hadRow ? 1 : 0);
  if (rows(after) !== expectedRows) throw new PatchError('internal: the ranking index changed shape unexpectedly.', 'internal');
}
// Completion status and display title of a backlog item, read ONLY from its leading text. Nested
// sub-items never close their parent: an open finding with several "FIXED" sub-points stays open.
//
// Supported leading forms (the README lists them):
//   ~~**Title**~~ Done 2026-09-24 / FIXED ... / **Fixed** ... / **Closed (...)** / **Done (...)**   -> done
//   **FIXED (2026-09-24).** text / **FIXED (date): title.** / **FIXED �?" title:**                      -> done
//   **FIXED (date), then reopened, ...**                                                              -> reopened
//   **Title �?" done except item 1.** / "partially fixed" in the lead bold                              -> partial
//   ~~**Title**~~ followed by anything else                                                           -> ambiguous
// Everything else is open. Only "done" leaves the Up next view; the other states are shown with a badge.

const DONE_WORD = /^(?:fixed|done|closed|resolved|completed|shipped)\b/i;

function boldLead(s) {
  const m = /^\*\*([\s\S]*?)\*\*/.exec(s);
  return m ? { inner: m[1], rest: s.slice(m[0].length) } : null;
}

export function detectStatus(lead) {
  const s = lead.trim();
  const strike = /^~~([\s\S]*?)~~/.exec(s);
  if (strike) {
    const after = s.slice(strike[0].length).replace(/^[\s:.,�?"�?"-]+/, '').replace(/^\*+/, '');
    const word = DONE_WORD.exec(after);
    if (word) return { status: 'done', note: firstClause(after) };
    return { status: 'ambiguous', note: 'struck through without a recognised status word' };
  }
  const bold = boldLead(s);
  const head = bold ? bold.inner.trim() : s;
  if (DONE_WORD.test(head)) {
    if (/re-?opened/i.test(head)) return { status: 'reopened', note: firstClause(head) };
    return { status: 'done', note: firstClause(head) };
  }
  if (bold && /\bdone except\b|\bpartially (?:fixed|done)\b/i.test(head)) {
    return { status: 'partial', note: firstClause(head.replace(/^.*?(?=done except|partially)/i, '')) };
  }
  return { status: 'open', note: null };
}

function firstClause(s) {
  const t = plain(s).trim();
  const cut = t.search(/(?<=[.:])\s/);
  const clause = cut === -1 ? t : t.slice(0, cut);
  return clause.length > 80 ? `${clause.slice(0, 77)}�?�` : clause;
}

/** Markdown emphasis/code markers removed, whitespace collapsed. */
export function plain(s) {
  return s.replace(/~~/g, '').replace(/\*\*/g, '').replace(/`/g, '').replace(/\s+/g, ' ').trim();
}

function trimTitle(t) {
  let s = plain(t).replace(/[\s.:;,�?"�?"-]+$/, '');
  if (s.length > 140) s = `${s.slice(0, 137)}�?�`;
  return s;
}

function firstSentence(s) {
  const t = plain(s);
  const m = /^(.+?[.!?])(?:\s|$)/.exec(t);
  return m ? m[1] : t;
}

export function extractTitle(lead) {
  let s = lead.trim();
  const strike = /^~~([\s\S]*?)~~/.exec(s);
  if (strike) return trimTitle(strike[1]);
  const bold = boldLead(s);
  if (bold) {
    const inner = bold.inner.trim();
    const status = /^(?:fixed|done|closed|resolved|completed|shipped)\b\s*(?:\([^)]*\))?\s*/i.exec(inner);
    if (!status) return trimTitle(inner);
    const remainder = inner.slice(status[0].length).replace(/^[:�?"�?"-]\s*/, '');
    if (remainder && !/^[,.]/.test(remainder) && !/^then\b/i.test(remainder)) return trimTitle(remainder);
    return trimTitle(firstSentence(bold.rest) || inner);
  }
  return trimTitle(firstSentence(s));
}

#!/bin/sh
# Structure-review pre-push gate (installed by /gate install).
# structure-gate: managed hook �?" replaced automatically from this template when it changes.
# Do NOT hand-edit an installed copy under .git/hooks; edit this template instead.
# Refuses a push while this repo has code changes pending review. A passing Claude review clears the
# marker, which lets the push through. Catches pushes made outside Claude too.
# Matches BOTH marker files: the queue (.structure-review-pending) and a review's claimed snapshot
# (.structure-review-pending.inflight). A review in flight must still block the push �?" during it the
# queue file is momentarily absent, and checking only that name would let an unreviewed push slip out.
root=$(git rev-parse --show-toplevel 2>/dev/null) || exit 0
# Git LFS: this managed hook occupies pre-push, so it must run LFS's upload step itself, or a push
# sends LFS pointers without their objects. Runs first (before any opt-out exit); only in repos that
# track files with LFS. It reads the ref list on stdin, which the gate below never needs.
if grep -qs 'filter=lfs' "$root/.gitattributes" && command -v git-lfs >/dev/null 2>&1; then
  git lfs pre-push "$@" || exit 1
fi
[ -f "$root/.structure-review-optout" ] && exit 0
[ -f "$root/.structure-review-paused" ] && exit 0
# Block only if a CODE edit is pending. The marker also records doc edits (as "k":"doc" lines, so a
# review knows the docs moved), but a docs-ONLY change needs no review and must not gate the push.
# Gate on content �?" a non-doc, non-empty marker line �?" not on the file merely existing, matching the
# CLI/Claude-hook logic. (A bare legacy path line has no "k" field and counts as code.)
for m in "$root"/.structure-review-pending*; do
  [ -e "$m" ] || continue
  if grep -v '"k":"doc"' "$m" 2>/dev/null | grep -qE '[^[:space:]]'; then
    echo "" >&2
    echo "  �o< structure-review: CODE changes in this repo are PENDING REVIEW." >&2
    echo "     Have Claude review them (a passing review clears the marker), then push." >&2
    echo "     Temporary bypass: touch .structure-review-paused  (or /gate pause)." >&2
    echo "" >&2
    exit 1
  fi
done
exit 0
// BACKLOG stable-ID scanning. Mirrors the ID shape tools/portal/src/backlog/parse.mjs already enforces
// (`ID_RE` there), but this module only does the two cross-document checks the checker's brief asks
// for �?" marker uniqueness and dangling references �?" not the portal's full ranking-index parse. Reuse
// tools/portal/src/backlog/parse.mjs directly for anything that needs BACKLOG.md's structure (sections,
// ranking, status); see baseline-snapshot.mjs.
const MARKER_RE = /<!--\s*(bl-[0-9a-f]{8})\s*-->/g;
const TOKEN_RE = /\bbl-[0-9a-f]{8}\b/g;

function splitLines(text) {
  return text.split(/\r\n|\n/);
}

/** Every `<!-- bl-xxxxxxxx -->` marker in BACKLOG.md, by id: `{ byId: Map<id, line[]>, duplicates }`.
 * `duplicates` is `[id, line[]][]` for ids that mark more than one line. */
export function scanMarkers(text) {
  const byId = new Map();
  splitLines(text).forEach((line, i) => {
    MARKER_RE.lastIndex = 0;
    let m;
    while ((m = MARKER_RE.exec(line))) {
      const id = m[1];
      if (!byId.has(id)) byId.set(id, []);
      byId.get(id).push(i + 1);
    }
  });
  const duplicates = [...byId.entries()].filter(([, lines]) => lines.length > 1);
  return { byId, duplicates };
}

/** Every bare `bl-xxxxxxxx` TOKEN in a document (marker or plain-text mention): `{ line, id }[]`. */
export function scanReferences(text) {
  const refs = [];
  splitLines(text).forEach((line, i) => {
    TOKEN_RE.lastIndex = 0;
    let m;
    while ((m = TOKEN_RE.exec(line))) refs.push({ line: i + 1, id: m[0] });
  });
  return refs;
}
// Declared document collections, read from tools/documentation/policy.json and shared by check.mjs and
// baseline-snapshot.mjs: which files together form the decision record set, which form the backlog, and
// which documents are historical (point-in-time evidence whose backticked paths are not expected to
// resolve today). Declared explicitly, never inferred from file names, so a stray copy of an old document
// is never mistaken for authority.
//
// A repo without policy.json (every synthetic test fixture, and the tree before the restructure) gets
// `null` from loadPolicy, and the collections fall back to the single legacy files: docs/DECISIONS.md and
// docs/BACKLOG.md alone, every document strict.
import fs from 'node:fs';
import path from 'node:path';

export const POLICY_REL = 'tools/documentation/policy.json';
const LEGACY = {
  decisions: { map: 'docs/DECISIONS.md', roots: [] },
  backlog: { register: 'docs/BACKLOG.md', shardRoots: [] },
  historical: [],
  impliedPrefixes: null,
};

/** The parsed policy.json, or null when the repo declares none. Throws on malformed JSON (a broken policy
 * must be loud, not silently ignored). */
export function loadPolicy(repoRoot, policyPath = null) {
  const file = policyPath || path.join(repoRoot, ...POLICY_REL.split('/'));
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, 'utf8'));
