/** Glob -> RegExp over repo-relative POSIX paths. `**` spans directories, `*` stays inside one segment. */
const GLOB_CACHE = new Map();
export function globToRegExp(glob) {
  if (GLOB_CACHE.has(glob)) return GLOB_CACHE.get(glob);
  let re = '';
  for (let i = 0; i < glob.length; i += 1) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      const slash = glob[i + 2] === '/';
      re += slash ? '(?:.*/)?' : '.*';
      i += slash ? 2 : 1;
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  const compiled = new RegExp(`^${re}$`);
  GLOB_CACHE.set(glob, compiled);
  return compiled;
}

export function matchesAny(rel, globs) {
  return (globs || []).some((g) => globToRegExp(g).test(rel));
}

function listMarkdown(repoRoot, relDir) {
  const out = [];
  const walk = (abs) => {
    let entries;
    try { entries = fs.readdirSync(abs, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const full = path.join(abs, e.name);
      if (e.isDirectory()) walk(full);
      else if (e.isFile() && e.name.toLowerCase().endsWith('.md')) out.push(path.relative(repoRoot, full).split(path.sep).join('/'));
    }
  };
  walk(path.join(repoRoot, ...relDir.split('/')));
  return out.sort();
}

/** The decision collection: the DECISIONS map plus every Markdown file under the declared record roots
 * (`docs/records/**`). `{ map, records: string[] }`, repo-relative. */
export function decisionCollection(repoRoot, policy) {
  const d = section(policy, 'decisions');
  const records = [];
  for (const root of d.roots || []) records.push(...listMarkdown(repoRoot, root));
  return { map: d.map, records: [...new Set(records)].sort() };
}

/** The backlog collection: the register (docs/BACKLOG.md, the ranking index) plus every shard under the
 * declared shard roots (docs/work/backlog/open, .../done). `{ register, shards: string[] }`. */
export function backlogCollection(repoRoot, policy) {
  const b = section(policy, 'backlog');
  const shards = [];
  for (const root of b.shardRoots || []) {
    const abs = path.join(repoRoot, ...root.split('/'));
    let names = [];
    try { names = fs.readdirSync(abs).filter((n) => n.toLowerCase().endsWith('.md') && n.toLowerCase() !== 'readme.md'); } catch { /* none */ }
    for (const n of names.sort()) shards.push(`${root}/${n}`);
  }
  return { register: b.register, shards, placeholderIds: new Set(b.placeholderIds || []) };
}

/** True when `rel` is a declared historical document: its backticked paths are point-in-time and are
 * counted, not failed. Links and fragments in it are still checked strictly (they are navigation). */
export function isHistorical(rel, policy) {
  return matchesAny(rel, section(policy, 'historical'));
}

/** Prefixes a module-relative backticked path may omit (`Dev/Tests/...` meaning `Source/EvilEye/Dev/...`).
 * Declared in policy.json; null means "discover" (the legacy single-module heuristic in repo-scan). */
export function impliedPrefixes(policy) {
  return (policy && policy.impliedPrefixes) || null;
}
