// The backlog as the server sees it: read with a revision, present as a view model, and mutate one
// operation at a time (serialized) �?" re-read, compare revisions, patch, replace, then record the
// pending-change event. The event is appended only after the write succeeded; a no-op records nothing.
// Setting the "ask me more" flag also files a discussion request for the entry (src/claude/discussions.mjs);
// clearing it withdraws a request that flag created and that no session has raised yet.
//
// A partitioned backlog (src/backlog/shards.mjs) is read as one set: the register plus every shard under
// docs/work/backlog/open and done. Its revision covers every file; a save writes only the files that changed,
// growing shards first (an entry moved by Mark done / Reopen is written to its new shard before it leaves the
// old one, so an interrupted save can duplicate an entry, which the parser reports, but never lose one).
// Without shard folders the backlog is the single file docs/BACKLOG.md, with that file's own revision.
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { PRIORITY_LABELS, parseBacklog, parseBacklogSet, rankedItems, PRIORITIES } from './parse.mjs';
import { PatchError, applyOperation, applyOperationSet, editableText } from './patch.mjs';
import { DONE_DIR, OPEN_DIR, REGISTER_REL } from './shards.mjs';
import { plain } from './status.mjs';
import { DocumentError, encode, readDocument, replaceDocument } from '../storage/documents.mjs';
import { loadEvents, recordChange, unreviewed } from '../storage/events.mjs';
import { renderDocument } from '../documents/render.mjs';
import { closeDiscussions, openDiscussionFor, requestDiscussion, summarizeDiscussions } from '../claude/discussions.mjs';

export const BACKLOG_REL = REGISTER_REL;
const DOC_MENTION = /(?:^|[\s(`"'[])((?:docs|research)\/[\w./-]+\.(?:md|html)|(?:STRUCTURE|README|AGENTS)\.md)(?=$|[\s)`"'\],;:]|\.(?:\s|$))/g;

/** Catalogued documents an entry's text links to or names (`research/X.md`, docs/Y.md, STRUCTURE.md). */
function docRefsOf(text, links, exists) {
  const refs = new Set(links);
  for (const m of text.matchAll(DOC_MENTION)) if (exists(m[1])) refs.add(m[1]);
  return [...refs];
}

/** One revision for the whole set: the hash of every file's own revision, in path order. */
function setRevision(parts) {
  const h = createHash('sha256');
  for (const p of [...parts].sort((a, b) => a.rel.localeCompare(b.rel))) h.update(`${p.rel}\u0000${p.decoded.revision}\n`);
  return `sha256:${h.digest('hex')}`;
}

export class BacklogService {
  /** `docs` (optional): a DocumentCatalog, so entry links and doc mentions resolve to viewable documents. */
  constructor({ repoRoot, docs = null }) {
    this.repoRoot = repoRoot;
    this.docs = docs;
    this.file = path.join(repoRoot, ...BACKLOG_REL.split('/'));
    this.queue = Promise.resolve();
