      revision: decoded.revision, file: BACKLOG_REL, files: parts.map((p) => p.rel), items,
      index: { present: Boolean(doc.index), broken: Boolean(doc.index && doc.index.broken) },
      encoding: { bom: register.bom, eol: doc.eol === '\r\n' ? 'CRLF' : 'LF', lossless: decoded.lossless },
      problems: doc.problems,
      review: summarizeReview(log),
      discussions: summarizeDiscussions(log),
    };
  }

  /** Serialize mutations: each waits for the previous one to finish. */
  mutate(request) {
    const run = this.queue.then(() => this.#mutate(request));
    this.queue = run.catch(() => {});
    return run;
  }

  async #mutate({ revision, key, op }) {
    if (!op || typeof op !== 'object') throw new PatchError('Missing operation.');
    if (key) {
      const prior = loadEvents(this.repoRoot).keys.get(key);
      if (prior) return { ok: true, changed: true, replayed: true, revision: prior.to, id: prior.items?.[0]?.id, eventId: prior.id };
    }
    const { decoded, doc, parts } = await this.read();
    if (!decoded.lossless) throw new PatchError('The backlog is not valid UTF-8; the portal will not edit it.', 'encoding');
    if (revision !== decoded.revision) {
      const err = new DocumentError('The backlog changed since this page read it.', 'conflict');
      err.currentRevision = decoded.revision;
      throw err;
    }
    let result;
    let written;
    if (parts.length === 1) {
      result = applyOperation(decoded.text, op);
      if (!result.changed) return { ok: true, changed: false, revision: decoded.revision, id: result.id };
      written = [{ rel: BACKLOG_REL, revision: await replaceDocument(this.file, encode(result.text, decoded.bom), decoded.revision) }];
    } else {
      result = applyOperationSet({ register: { rel: BACKLOG_REL, text: parts[0].decoded.text },
        shards: parts.slice(1).map((p) => ({ rel: p.rel, text: p.decoded.text })) }, op);
      if (!result.changed) return { ok: true, changed: false, revision: decoded.revision, id: result.id };
      written = await this.#writeSet(parts, result.texts);
    }
    const newRevision = parts.length === 1 ? written[0].revision
      : setRevision(parts.map((p) => ({ rel: p.rel, decoded: { revision: written.find((w) => w.rel === p.rel)?.revision || p.decoded.revision } })));
    const after = parts.length === 1 ? parseBacklog(result.text)
      : parseBacklogSet({ register: { rel: BACKLOG_REL, text: result.texts.get(BACKLOG_REL) ?? parts[0].decoded.text },
        shards: parts.slice(1).map((p) => ({ rel: p.rel, text: result.texts.get(p.rel) ?? p.decoded.text })) });
    const item = after.items.find((it) => it.id === result.id);
    const before = doc.items.find((it) => it.id === result.id);
    const event = recordChange(this.repoRoot, {
      kind: op.type, key, from: decoded.revision, to: newRevision, files: written.map((w) => w.rel),
      items: item ? [{ id: item.id, title: item.title, priority: item.priority }] : [],
      summary: describe(op, before, item),
    });
    const discussion = op.type === 'flags' && item ? this.#followAskFlag(before, item, after, key) : null;
    return { ok: true, changed: true, revision: newRevision, id: result.id, eventId: event.id, discussion };
  }

  /** Write the changed files of a set, each against its own revision: growing shards first, the register last. */
  async #writeSet(parts, texts) {
    const byRel = new Map(parts.map((p) => [p.rel, p.decoded]));
    const order = [...texts.keys()].sort((a, b) => {
      const rank = (rel) => (rel === BACKLOG_REL ? 2 : texts.get(rel).length >= byRel.get(rel).text.length ? 0 : 1);
      return rank(a) - rank(b) || a.localeCompare(b);
    });
    const written = [];
    for (const rel of order) {
      const d = byRel.get(rel);
      written.push({ rel, revision: await replaceDocument(this.abs(rel), encode(texts.get(rel), d.bom), d.revision) });
    }
    return written;
  }

  /** "ask me more" set: file a discussion request (unless one is open). Cleared: withdraw its unraised request. */
  #followAskFlag(before, after, afterDoc, key) {
    const had = before?.flags.includes('ask');
    const has = after.flags.includes('ask');
    if (has && !had) {
      const req = requestDiscussion(this.repoRoot, { item: { ...after, file: after.file || BACKLOG_REL, text: editableText(afterDoc, after).text }, origin: 'ask-flag', key: key ? `${key}:ask` : null });
      return { id: req.id, state: req.state || 'waiting', existing: Boolean(req.existing) };
    }
    if (had && !has) {
      const open = openDiscussionFor(loadEvents(this.repoRoot), after.id);
      if (open && open.origin === 'ask-flag' && open.state === 'waiting') {
        closeDiscussions(this.repoRoot, [open.id], 'withdrawn', { by: 'owner', note: 'ask me more flag cleared' });
        return { id: open.id, state: 'withdrawn' };
      }
    }
    return null;
  }

  /** An entry by ID for a discussion request: { id, title, priority, file, line, text }, or null. */
  async findItem(id) {
    const { doc } = await this.read();
    const it = doc.items.find((x) => x.id === id);
    return it ? { id: it.id, title: it.title, priority: it.priority, file: it.file || BACKLOG_REL, line: it.line, text: editableText(doc, it).text, status: it.status } : null;
  }
}

export function summarizeReview(log) {
  const waiting = unreviewed(log);
  return {
    waiting: waiting.length,
    delivered: waiting.filter((ev) => ev.state === 'delivered').length,
    malformedLines: log.malformed.length,
    log: log.records, // changes whenever anything is appended (edits, deliveries, acks, discussion requests)
    recent: waiting.slice(-20).reverse().map((ev) => ({ id: ev.id, at: ev.at, summary: ev.summary, state: ev.state })),
  };
}

function describe(op, before, after) {
  const title = `"${(after || before)?.title || op.id}"`;
  const label = (p) => PRIORITY_LABELS[p] || p;
  switch (op.type) {
    case 'add': return `Added ${title} to ${label(after.priority)}`;
    case 'edit': return `Edited ${title}`;
    case 'priority': return `Priority of ${title}: ${label(before.priority)} �+' ${label(after.priority)}`;
    case 'flags': return `Flags on ${title}: ${after.flags.length ? after.flags.map((f) => (f === 'ask' ? 'ask me more' : 'research needed')).join(', ') : 'cleared'}`;
    case 'move': return `Moved ${title} #${before.rank} �+' #${after.rank} in ${label(after.priority)}`;
    case 'index': return `Ranked ${title} in ${label(after.priority)} (was unindexed)`;
    case 'complete': return `Marked ${title} done`;
    case 'reopen': return `Reopened ${title} in ${label(after.priority)}`;
    default: return `${op.type} ${title}`;
  }
}
#!/usr/bin/env node
// Portal lifecycle: resolve the checkout, bind 127.0.0.1:<port>, publish an instance file (PID, port,
// instance id, shutdown token) in the checkout's state directory so Start/Stop-Portal.ps1 can verify
// identity, and exit 0 on a requested shutdown (the logon task restarts only on failure).
//   node src/server/main.mjs [--repo <checkout>] [--port <n>]
import { randomBytes } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { BacklogService } from '../backlog/service.mjs';
import { DocumentCatalog } from '../documents/catalog.mjs';
import { canonicalCheckout, ownCheckout, stateDir } from '../storage/state.mjs';
import { createPortalServer } from './http.mjs';

export const DEFAULT_PORT = 47815;
export const EXIT_PORT_IN_USE = 3;
const here = path.dirname(fileURLToPath(import.meta.url));
const pkg = JSON.parse(fs.readFileSync(path.join(here, '..', '..', 'package.json'), 'utf8'));

function parseArgs(argv) {
  const args = { repo: process.env.EVILEYE_PORTAL_REPO || ownCheckout(), port: Number(process.env.EVILEYE_PORTAL_PORT) || DEFAULT_PORT,
    log: null, printStateDir: false };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--repo') args.repo = argv[++i];
    else if (argv[i] === '--port') args.port = Number(argv[++i]);
    else if (argv[i] === '--log') args.log = argv[++i];
    else if (argv[i] === '--state-dir') args.printStateDir = true;
    else throw new Error(`Unknown argument ${argv[i]}`);
  }
  if (!Number.isInteger(args.port) || args.port < 1024 || args.port > 65535) throw new Error('--port must be 1024-65535');
  return args;
}

export async function startPortal({ repo, port, webDir = path.join(here, '..', '..', 'web'), writeInstance = true }) {
  const repoRoot = path.resolve(repo);
  if (!fs.existsSync(path.join(repoRoot, 'docs', 'BACKLOG.md'))) throw new Error(`${repoRoot} has no docs/BACKLOG.md`);
  const instance = { id: randomBytes(8).toString('hex'), token: randomBytes(24).toString('hex'), version: pkg.version,
    repo: canonicalCheckout(repoRoot), startedAt: new Date().toISOString() };
  const docs = new DocumentCatalog({ repoRoot });
  const service = new BacklogService({ repoRoot, docs });
  const instanceFile = path.join(stateDir(repoRoot, { create: writeInstance }), 'instance.json');
  let server;
  const stop = () => new Promise((resolve) => {
    server.close(() => resolve());
    server.closeAllConnections?.();
  }).finally(() => {
    try {
      const current = JSON.parse(fs.readFileSync(instanceFile, 'utf8'));
      if (current.id === instance.id) fs.rmSync(instanceFile, { force: true });
    } catch { /* already gone */ }
  });
  server = createPortalServer({ port, service, docs, instance, webDir, onShutdown: () => stop().then(() => process.exit(0)) });
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen({ host: '127.0.0.1', port, exclusive: true }, resolve);
  });
  const actualPort = server.address().port;
  if (writeInstance) {
    fs.writeFileSync(instanceFile, JSON.stringify({ ...instance, pid: process.pid, port: actualPort }, null, 2), { mode: 0o600 });
  }
  return { server, instance, port: actualPort, stop, instanceFile };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  let args;
  try { args = parseArgs(process.argv.slice(2)); } catch (err) { console.error(err.message); process.exit(2); }
  if (args.printStateDir) {
    console.log(stateDir(path.resolve(args.repo), { create: true }));
    process.exit(0);
  }
  if (args.log) {
    // Launched detached (no console to inherit): append our own output to the log file.
    const out = fs.createWriteStream(args.log, { flags: 'a' });
    const write = (prefix) => (...parts) => out.write(`${prefix}${parts.map(String).join(' ')}\n`);
    console.log = write('');
    console.error = write('[error] ');
    process.on('uncaughtException', (err) => { console.error(err.stack || err.message); process.exitCode = 1; out.end(() => process.exit(1)); });
  }
  startPortal(args).then(({ port, stop, instance }) => {
    console.log(`[portal] ${new Date().toISOString()} listening on http://127.0.0.1:${port}/ for ${instance.repo} (pid ${process.pid}, instance ${instance.id})`);
    const quit = () => stop().then(() => process.exit(0));
    process.on('SIGINT', quit);
    process.on('SIGTERM', quit);
  }).catch((err) => {
    if (err.code === 'EADDRINUSE') {
      console.error(`[portal] port ${args.port} is already in use by another program. Stop it or pass --port.`);
      setTimeout(() => process.exit(EXIT_PORT_IN_USE), 200); // let a --log stream flush
      return;
    }
    console.error(`[portal] failed to start: ${err.stack || err.message}`);
    setTimeout(() => process.exit(1), 200);
  });
}
// HTTP boundary: loopback-only request validation, static assets and the JSON API. These are browser
// boundary checks (DNS rebinding, cross-site requests), not accounts: anything running as the user on
// this PC can already edit the file directly.
//   - Host must be 127.0.0.1:<port> or localhost:<port>; a foreign Origin or cross-site fetch is refused.
//   - No CORS headers are ever sent. Mutations need POST + application/json + the X-Portal-Request header
//     (a custom header forces a preflight that this server never approves).
//   - Bodies are capped; static files come from a fixed name map, never from a path built from the URL.
//   - Documents are read only through the catalog (src/documents/); research previews are served with a
//     CSP sandbox (no scripts, opaque origin) for a sandboxed iframe. There is no document write endpoint.
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { PatchError } from '../backlog/patch.mjs';
import { DocumentError, readDocument } from '../storage/documents.mjs';
import { renderDocument } from '../documents/render.mjs';
import { PathError } from '../documents/paths.mjs';
import { DiscussError } from '../claude/discussions.mjs';
import { HttpError, checkMutation, readJson } from './request.mjs';
import { documentRoutes, previewResponse } from './document-routes.mjs';
import { discussRoutes } from './discuss-routes.mjs';

export { MAX_BODY } from './request.mjs';
const FEATURES_REL = 'docs/FEATURES.md';
const STATIC_TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' };
const SECURITY_HEADERS = {
  'Content-Security-Policy': "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; "
    + "connect-src 'self'; font-src 'self'; frame-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'Cross-Origin-Resource-Policy': 'same-origin',
  'Cross-Origin-Opener-Policy': 'same-origin',
  'X-Frame-Options': 'DENY',
};

/** Static assets: every file directly in web/ with a known extension, looked up by exact name. */
export function loadStaticMap(webDir) {
  const map = new Map();
  for (const name of fs.readdirSync(webDir)) {
    const ext = path.extname(name);
    if (!/^[a-z0-9-]+\.[a-z]+$/.test(name) || !STATIC_TYPES[ext]) continue;
    map.set(`/${name}`, { file: path.join(webDir, name), type: STATIC_TYPES[ext] });
  }
  map.set('/', map.get('/index.html'));
  return map;
}

function send(res, status, body, headers = {}) {
  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
  res.writeHead(status, { ...SECURITY_HEADERS, 'Cache-Control': 'no-store',
    'Content-Type': typeof body === 'object' && !Buffer.isBuffer(body) ? 'application/json; charset=utf-8' : 'text/plain; charset=utf-8',
    ...headers });
  res.end(payload);
}

export function checkBoundary(req, port) {
  const hosts = [`127.0.0.1:${port}`, `localhost:${port}`];
  const host = (req.headers.host || '').toLowerCase();
  if (!hosts.includes(host)) throw new HttpError(421, 'Unexpected Host header; the portal answers only on 127.0.0.1.');
  const origin = req.headers.origin;
  if (origin !== undefined && !hosts.map((h) => `http://${h}`).includes(origin.toLowerCase())) {
    throw new HttpError(403, 'Cross-origin requests are not allowed.');
  }
  const site = req.headers['sec-fetch-site'];
  if (site && !['same-origin', 'none'].includes(site)) throw new HttpError(403, 'Cross-site requests are not allowed.');
}

function errorResponse(err) {
  if (err instanceof HttpError) return [err.status, { error: err.message, ...err.extra }];
  if (err instanceof PathError) return [404, { error: err.message }];
  if (err instanceof DiscussError) return [err.code === 'open' ? 409 : 422, { error: err.message, code: err.code, request: err.request }];
  if (err instanceof DocumentError) {
    if (err.code === 'conflict') return [409, { error: err.message, conflict: true, currentRevision: err.currentRevision }];
    if (err.code === 'locked') return [423, { error: err.message, locked: true }];
    if (err.code === 'missing') return [404, { error: err.message }];
    return [500, { error: err.message }];
  }
  if (err instanceof PatchError) {
    const status = err.code === 'stale' || err.code === 'missing' ? 409 : err.code === 'internal' ? 500 : 422;
    return [status, { error: err.message, code: err.code, conflict: status === 409 }];
  }
  return [500, { error: `Internal error: ${err.message}` }];
}

export function createPortalServer({ port, service, docs, instance, webDir, onShutdown }) {
  const statics = loadStaticMap(webDir);
  const featuresFile = path.join(service.repoRoot, ...FEATURES_REL.split('/'));

  const routes = {
    'GET /api/health': async () => ({ app: 'evileye-portal', version: instance.version, instance: instance.id,
      repo: instance.repo, pid: process.pid, port: boundPort(), startedAt: instance.startedAt }),
    'GET /api/backlog': async () => service.view(),
    'GET /api/backlog/revision': async () => service.pulse(),
    'POST /api/backlog/mutate': async (req) => {
      checkMutation(req);
      const body = await readJson(req);
      if (!body || typeof body.revision !== 'string' || !body.op) throw new HttpError(400, 'Expected { revision, key, op }.');
      if (body.key !== undefined && (typeof body.key !== 'string' || body.key.length > 100)) throw new HttpError(400, 'Bad idempotency key.');
      return service.mutate(body);
    },
    // FEATURES is a map of links into the handbook: render it like any catalogued document, so a relative link
    // resolves against docs/FEATURES.md and opens in the document pane (the old base-less render left every
    // relative link inert).
    'GET /api/features': async () => {
      const doc = await readDocument(featuresFile);
      const rendered = renderDocument(doc.text, { base: FEATURES_REL, exists: (p) => Boolean(docs && docs.has(p)) });
      return { file: FEATURES_REL, revision: doc.revision, html: rendered.html, headings: rendered.headings };
    },
    ...documentRoutes(docs),
    ...discussRoutes(service),
    'POST /api/shutdown': async (req) => {
      checkMutation(req);
      if (req.headers['x-portal-token'] !== instance.token) throw new HttpError(403, 'Wrong shutdown token.');
      setImmediate(() => onShutdown && onShutdown());
      return { stopping: true, instance: instance.id };
    },
  };

  const server = http.createServer(async (req, res) => {
    try {
      checkBoundary(req, boundPort());
      const url = new URL(req.url, 'http://127.0.0.1');
      const handler = routes[`${req.method} ${url.pathname}`];
      if (handler) { send(res, 200, await handler(req, url)); return; }
      if (req.method === 'GET' && url.pathname === '/preview') {
        const preview = await previewResponse(docs, url);
        send(res, 200, preview.body, preview.headers);
        return;
      }
      if (url.pathname.startsWith('/api/')) throw new HttpError(404, 'No such endpoint.');
      if (req.method !== 'GET' && req.method !== 'HEAD') throw new HttpError(405, 'Method not allowed.');
      const asset = statics.get(url.pathname);
      if (!asset) throw new HttpError(404, 'Not found.');
      send(res, 200, fs.readFileSync(asset.file), { 'Content-Type': asset.type, 'Cache-Control': 'no-cache' });
    } catch (err) {
      const [status, body] = errorResponse(err);
      if (status >= 500) console.error(`[portal] ${req.method} ${req.url}: ${err.stack || err.message}`);
      if (!res.headersSent) send(res, status, body);
      else res.destroy();
    }
  });
  // The port actually bound (a test may pass 0 and let the OS choose).
  function boundPort() { return server.address()?.port || port; }
  server.requestTimeout = 30000;
  server.headersTimeout = 10000;
  return server;
}
